#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

int main() {
    std::string s, ss = "";
    int i, flag = 0, max = 0;
    std::getline(std::cin, s);
    std::getline(std::cin, s);
    // Replace all underscores with spaces and trim
    std::replace(s.begin(), s.end(), '_', ' ');
    s.erase(s.begin(), std::find_if(s.begin(), s.end(), [](unsigned char ch) { return !std::isspace(ch); }));
    s.erase(std::find_if(s.rbegin(), s.rend(), [](unsigned char ch) { return !std::isspace(ch); }).base(), s.end());

    for (i = 0; i < (int)s.length(); i++) {
        if (s[i] == '(')
            flag = 1;
        else if (s[i] == ')') {
            ss += " ";
            flag = 0;
        } else if (flag == 1)
            ss += s[i];
    }

    for (i = 0; i < (int)s.length(); i++) {
        if (s[i] == ')') {
            size_t pos = s.find('(');
            if (pos != std::string::npos) {
                s = s.substr(0, pos) + " " + s.substr(i + 1);
                i = 0;
            }
        }
    }

    // Remove trailing spaces
    s.erase(s.begin(), std::find_if(s.begin(), s.end(), [](unsigned char ch) { return !std::isspace(ch); }));
    s.erase(std::find_if(s.rbegin(), s.rend(), [](unsigned char ch) { return !std::isspace(ch); }).base(), s.end());

    // Replace multiple spaces with single space
    std::string::iterator new_end = std::unique(s.begin(), s.end(), [](char lhs, char rhs){ return std::isspace(lhs) && std::isspace(rhs); });
    s.erase(new_end, s.end());
    // Trim again
    s.erase(s.begin(), std::find_if(s.begin(), s.end(), [](unsigned char ch) { return !std::isspace(ch); }));
    s.erase(std::find_if(s.rbegin(), s.rend(), [](unsigned char ch) { return !std::isspace(ch); }).base(), s.end());

    // Same for ss
    ss.erase(ss.begin(), std::find_if(ss.begin(), ss.end(), [](unsigned char ch) { return !std::isspace(ch); }));
    ss.erase(std::find_if(ss.rbegin(), ss.rend(), [](unsigned char ch) { return !std::isspace(ch); }).base(), ss.end());
    new_end = std::unique(ss.begin(), ss.end(), [](char lhs, char rhs){ return std::isspace(lhs) && std::isspace(rhs); });
    ss.erase(new_end, ss.end());

    std::istringstream out_stream(s);
    std::vector<std::string> out;
    std::string token;
    while (out_stream >> token) {
        out.push_back(token);
    }

    std::istringstream in_stream(ss);
    std::vector<std::string> in;
    while (in_stream >> token) {
        in.push_back(token);
    }

    for (const auto& word : out) {
        if ((int)word.length() > max)
            max = word.length();
    }

    if (!ss.empty() && ss != " ")
        std::cout << max << " " << in.size() << std::endl;
    else
        std::cout << max << " 0" << std::endl;

    return 0;
}
